<template><section class="trash-view"><header><h1>Trash</h1><el-button @click="load()">Refresh</el-button></header><p>Messages are permanently deleted 30 days after they enter Trash.</p><el-input v-model="query" placeholder="Search Trash" aria-label="Search Trash" @change="load()"/><p v-if="error" role="alert">{{error}}</p><p v-if="!messages.length">Trash is empty.</p><article v-for="message in messages" :key="message.emailId"><button class="message" @click="open(message)"><strong>{{message.subject||'(No subject)'}}</strong><span>{{message.sendEmail}}</span><span>{{message.preview}}</span></button><div class="actions"><el-button @click="action(message,'restore')">Restore</el-button><el-button type="danger" plain @click="action(message,'purge')">Delete permanently</el-button></div></article><el-button v-if="cursor" @click="load(true)">Load more</el-button><el-dialog v-model="show" :title="detail?.subject||'Message'"><p>From: {{detail?.sendEmail}}</p><pre class="body">{{detail?.text||plainHTML(detail?.content)}}</pre><p v-for="file in detail?.attList||[]" :key="file.attId"><el-button @click="download(file)">{{file.filename}}</el-button></p><template #footer><el-button @click="show=false">Close</el-button></template></el-dialog></section></template>
<script setup>
import {ref,onActivated,onMounted} from 'vue';
import http from '@/axios';
import {ElMessageBox} from 'element-plus';
const messages=ref([]),query=ref(''),cursor=ref(null),error=ref(''),show=ref(false),detail=ref(null);
function plainHTML(html){return new DOMParser().parseFromString(html||'','text/html').body.textContent;}
async function load(more=false){try{const page=await http.get('/v1/messages',{params:{folder:'trash',q:query.value,cursor:more?cursor.value:undefined}});messages.value=more?[...messages.value,...page.messages]:page.messages;cursor.value=page.nextCursor;error.value='';}catch(e){error.value=e.message||'Could not load Trash.';}}
async function open(message){try{detail.value=await http.get(`/v1/messages/${message.emailId}`);show.value=true;}catch(e){error.value=e.message;}}
async function action(message,action){try{if(action==='purge')await ElMessageBox.confirm('Permanently delete this message and its files? This cannot be undone.',{confirmButtonText:'Delete permanently',type:'warning'});await http.post(`/v1/messages/${action}`,{emailIds:[message.emailId]});await load();}catch(e){if(e!=='cancel'&&e!=='close')error.value=e.message||'The action failed.';}}
async function download(file){try{const blob=await http.get(`/v1/attachments/${file.attId}/content`,{responseType:'blob'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.filename||'attachment';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=e.message;}}
onMounted(load);onActivated(load);
</script>
<style scoped>.trash-view{padding:24px;overflow:auto;height:100%;box-sizing:border-box;background:var(--mail-surface);border-radius:16px}header,.actions{display:flex;gap:12px;justify-content:space-between;align-items:center}article{padding:18px 0;border-bottom:1px solid #8883}.message{display:flex;flex-direction:column;gap:5px;text-align:left;background:none;border:0;color:inherit;cursor:pointer;width:100%;margin-bottom:12px}.body{white-space:pre-wrap;overflow-wrap:anywhere}</style>
